/* Interactive workflow extension. Synthetic records, isolated session storage, no APIs. */
window.createTicketWorkflow = function (c) {
  'use strict';
  const {state:s,$,root,esc,icon,badge,button,link,empty,openDialog,closeDialog,modalFoot,
    requiredField,validate,toast,recordEvent,person,sampleUsers,technicians,initials,displayStamp,
    durationLabel:baseDuration,go,render,renderComposer,setDirty,original,groups,meter} = c;
  const durationLabel=value=>baseDuration(Math.max(0,Math.round(value)));
  const KEY='oblivion-ticket-mockup-workflow-v4';
  const names=['Jordan Lee','Avery Taylor','Casey Morgan'];
  const fmt=new Intl.DateTimeFormat('en-CA',{timeZone:'Pacific/Auckland',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
  function local(instant=Date.now()){const p=Object.fromEntries(fmt.formatToParts(new Date(instant)).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;}
  // Validate both NZ offsets. Ambiguous and nonexistent DST wall times require correction.
  function instant(wall){if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(wall||''))return NaN;const base=Date.parse(wall+'Z');const found=[720,780].map(offset=>base-offset*60000).filter(value=>local(value)===wall);return found.length===1?found[0]:NaN;}
  const today=()=>local().slice(0,10);
  const stamp=value=>value?displayStamp(value):'Not set';
  const short=value=>value?stamp(value).split(', ')[1]:'Not set';
  const uid=()=>crypto.randomUUID();
  const draft=()=>s.drafts[s.audience];
  const money=value=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD'}).format(value);
  const field=(id,label,value='',type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
  const select=(id,label,options,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
  const error=()=>'<p class="field-error" id="workflow-error" role="alert" hidden></p>';
  function fail(text){const el=$('workflow-error')||$('note-time-error');if(el){el.textContent=text;el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(text);return false;}
  s.followUp={action:'Confirm workstation test print',owner:'Jordan Lee',due:'2026-09-13T12:45',waitingOn:'Affected user',reason:s.waitReason};
  s.diagnostics={onset:'2026-09-13T08:55',affected:'8',location:'Harbour Office · Level 1 print area',impact:'Office team cannot use the main printer',workaround:'Use the meeting-room printer',access:'Check in at reception. Arrange workstation access with the affected user.',vendor:'Harbour Print Support · Case HPS-1042',contract:'Printer support agreement · Example reference',steps:'Network reachability passed; queue port corrected; local test page printed. Workstation test remains open.'};
  s.contactPreferences={maya:{method:'Support portal',window:'After 12:30 pm today',alternate:'omar'},omar:{method:'Work phone',window:'Confirm before calling',alternate:'priya'},priya:{method:'Work email',window:'Confirm availability',alternate:'omar'}};
  s.costs=[];s.rates={standard:85,afterHours:127.5};s.corrections=[];s.completedOps=[];s.slaChanged=false;s.priority='P2';s.priorityReason='Original High priority carried into the P1–P4 scale.';
  let restoredDrafts=null,storageError=false,booking=null,editing=null,splitRows=null,decision=null,undoVisit=null;
  try{const saved=JSON.parse(sessionStorage.getItem(KEY)||'null');if(saved?.version===4){Object.assign(s,saved.state,{busy:false,load:'ready'});if(Object.values(s.drafts).some(d=>d.text||d.time?.start||d.time?.timer?.segments?.length)){restoredDrafts=structuredClone(s.drafts);s.drafts={public:{text:'',files:[],error:false},internal:{text:'',files:[],error:false}};}}}catch{storageError=true;}
  function persist(){try{sessionStorage.setItem(KEY,JSON.stringify({version:4,state:{...s,drafts:restoredDrafts||s.drafts,busy:false,load:'ready'}}));storageError=false;}catch{storageError=true;}}
  function history(kind,id,before,after,reason){s.corrections.unshift({id:uid(),kind,record:id,at:local(),by:'Jordan Lee',reason,before:structuredClone(before),after:structuredClone(after)});recordEvent('Pencil',`${kind} corrected by Jordan Lee`,reason,'work');}
  function workMinutes(e){if(e.segments?.length)return e.segments.reduce((n,x)=>n+(x.end-x.start)/60000,0);return Math.round((instant(e.end)-instant(e.start))/60000)-(Number(e.breakMinutes)||0);}
  function initDraft(){const d=draft();d.time??={enabled:s.audience==='internal',start:'',end:'',type:'Remote support',afterHours:false};d.time.date??=today();d.time.endDate??=d.time.date;d.time.breakMinutes??=0;d.time.technician??='Jordan Lee';d.workflow??={status:'keep',action:s.followUp.action,due:s.followUp.due,owner:s.followUp.owner,waitingOn:s.followUp.waitingOn,reason:s.followUp.reason,outcome:'Service restored',verification:'',publicSummary:''};d.recipients??=[...new Set([s.requesterId,s.affectedId])];d.operationId??=uid();return d;}
  function timerMinutes(t){const tm=t.timer;if(!tm)return 0;return (tm.segments.reduce((n,p)=>n+p.end-p.start,0)+(tm.runningSince?Date.now()-tm.runningSince:0))/60000;}
  function timeFields(){const d=initDraft(),t=d.time,tm=t.timer;return `<section class="note-time" aria-label="Time for this note"><label class="note-time-toggle"><input id="note-log-time" type="checkbox" ${t.enabled?'checked':''}><strong>Log time with this ${s.audience==='internal'?'note':'reply'}</strong><span>Internal work record</span></label>${t.enabled?`<fieldset ${s.busy?'disabled':''}><legend class="sr-only">Actual time worked</legend><div class="timer-bar"><span>${icon('Timer')}<strong id="timer-value">${tm?durationLabel(timerMinutes(t)):'Timer ready'}</strong><small>${tm?.runningSince?'Running':tm?.status==='paused'?'Paused · break excluded':tm?.status==='stopped'?'Stopped · review actual time':'Optional · manual entry also available'}</small></span><div class="row">${!tm||tm.status==='stopped'?button('Start','timer-start','Timer','compact'):tm.runningSince?button('Pause','timer-pause','Clock3','compact'):button('Resume','timer-resume','Timer','compact')}${tm&&tm.status!=='stopped'?button('Stop','timer-stop','Check','compact'):''}</div></div><div class="time-input-grid">${field('work-date','Work date',t.start?.slice(0,10)||t.date,'date')}${field('work-start','Started',t.start?.slice(11)||'','time')}${field('work-end','Ended',t.end?.slice(11)||'','time')}${field('work-end-date','End date',t.end?.slice(0,10)||t.endDate,'date')}</div><div class="note-time-meta"><span>${esc(t.technician)}${t.technician==='Jordan Lee'?' (you)':' · Recorded by Jordan Lee'} · Pacific/Auckland</span><strong id="note-duration">${Number.isFinite(workMinutes(t))&&workMinutes(t)>0?durationLabel(workMinutes(t)):'Enter start and end'}</strong></div><div class="time-options-grid">${select('work-type','Work type',['Remote support','On site','Travel'],t.type)}${field('work-break','Break minutes',t.breakMinutes,'number','min="0" step="1" '+(t.segments?.length?'disabled':''))}<label class="after-hours-choice"><input id="work-after-hours" type="checkbox" ${t.afterHours?'checked':''}><span><strong>Work was done after hours</strong><small>Applies to this entry; no rate is inferred.</small></span></label></div><div class="split-summary">${button('Review after-hours split','split-time','Clock3','ghost compact')}<span>${t.parts?.length?`${t.parts.length} reviewed portions · ${durationLabel(t.parts.filter(p=>p.afterHours).reduce((n,p)=>n+workMinutes(p),0))} after hours`:'Example support hours: Mon–Fri, 8:30 am–5 pm'}</span></div>${d.visitId?`<div class="inline-alert">${icon('CalendarDays')}Saving this note and actual time completes ${esc(t.technician)}’s part of the planned visit.</div>`:''}<p class="small muted">The note above describes this work. Paused timer periods are excluded. Overnight work uses the end date.</p><p id="note-time-error" class="field-error" role="alert" ${d.timeError?'':'hidden'}>${esc(d.timeError||'')}</p></fieldset>`:''}</section>`;}
  function captureTime(){const d=initDraft(),t=d.time;if($('note-log-time'))t.enabled=$('note-log-time').checked;if($('work-date')){t.date=$('work-date').value;t.endDate=$('work-end-date').value;t.start=$('work-start').value?t.date+'T'+$('work-start').value:'';t.end=$('work-end').value?t.endDate+'T'+$('work-end').value:'';t.breakMinutes=Number($('work-break').value);t.type=$('work-type').value;t.afterHours=$('work-after-hours').checked;}persist();return t;}
  function captureWorkflow(){const d=initDraft();if($('note-status'))['status','action','due','owner','waitingOn','reason','outcome','verification','publicSummary'].forEach(k=>{if($('note-'+k))d.workflow[k]=$('note-'+k).value;});persist();}
  function timeError(t,exclude=[]){if(!t.enabled)return '';if(t.timer?.runningSince||t.timer?.status==='paused')return 'Stop the timer before saving this work.';const parts=t.parts||[t];if(!parts.length)return 'Enter actual worked time.';for(const p of parts){if(!Number.isFinite(instant(p.start))||!Number.isFinite(instant(p.end)))return 'Enter valid dates and times. An ambiguous daylight-saving time needs clarification.';if(workMinutes(p)<=0)return 'End must follow start, and breaks must be shorter than the elapsed time.';if(p.breakMinutes<0)return 'Break minutes cannot be negative.';const hit=s.timeEntries.find(e=>!exclude.includes(e.id)&&e.technician===(t.technician||'Jordan Lee')&&instant(p.start)<instant(e.end)&&instant(p.end)>instant(e.start));if(hit)return `This overlaps ${hit.technician}’s ${stamp(hit.start)} entry. Correct the times before saving.`;}return '';}
  function timerAction(kind){const t=captureTime(),now=Date.now();t.enabled=true;t.parts=null;if(kind==='start'){if(t.timer?.segments?.length)return openDialog('timer-reset','Start a new timer?','The previous stopped timer is already in the time fields.',`<p>Save its note first, or explicitly replace its unsaved timing.</p>`,modalFoot(button('Replace unsaved timer','timer-replace','Timer','primary')));t.timer={status:'running',segments:[],runningSince:now};t.start=local(now);t.date=t.start.slice(0,10);t.end='';t.segments=null;t.breakMinutes=0;}else{const tm=t.timer;if(!tm)return;if(kind==='resume'){tm.runningSince=now;tm.status='running';}else{if(tm.runningSince){tm.segments.push({start:tm.runningSince,end:now});tm.runningSince=null;}tm.status=kind==='pause'?'paused':'stopped';if(kind==='stop'){t.segments=structuredClone(tm.segments);t.start=local(tm.segments[0]?.start||now);t.end=local(now);t.date=t.start.slice(0,10);t.endDate=t.end.slice(0,10);t.breakMinutes=0;}}}persist();renderComposer();}
  function splitTime(){const t=captureTime();const problem=timeError({...t,parts:null});if(problem)return fail(problem);const intervals=t.segments?.length?t.segments.map(p=>({start:p.start,end:p.end})):[{start:instant(t.start),end:instant(t.end)}];splitRows=[];for(const range of intervals){for(let cursor=range.start;cursor<range.end;){const wall=local(cursor),day=wall.slice(0,10),weekday=new Date(day+'T12:00Z').getUTCDay(),hm=wall.slice(11),standard=weekday>0&&weekday<6&&hm>='08:30'&&hm<'17:00';const nextDay=new Date(Date.parse(day+'T00:00Z')+86400000).toISOString().slice(0,10);const boundaries=[day+'T08:30',day+'T17:00',nextDay+'T00:00'].map(instant).filter(x=>x>cursor);const end=Math.min(range.end,...boundaries);splitRows.push({start:local(cursor),end:local(end),afterHours:!standard,breakMinutes:0,type:t.type,technician:t.technician});cursor=end;}}
    openDialog('split','Review time portions','Example support hours only. Review the after-hours flags before applying.',`<p class="small muted">One note can link to these separate work entries. Allocate ${t.breakMinutes||0} break minutes across the portions.</p><div class="split-rows">${splitRows.map((p,i)=>`<div class="split-row"><strong>${stamp(p.start)} → ${stamp(p.end)}</strong><span>${durationLabel(workMinutes(p))} elapsed</span><label><input type="checkbox" data-split-flag="${i}" ${p.afterHours?'checked':''}> After hours</label><label>Break minutes <input type="number" min="0" value="0" data-split-break="${i}"></label></div>`).join('')}</div>${error()}`,modalFoot(button('Apply reviewed split','apply-split','Check','primary')),900);}
  function applySplit(){const t=initDraft().time;const rows=splitRows.map((p,i)=>({...p,afterHours:root.querySelector(`[data-split-flag="${i}"]`).checked,breakMinutes:Number(root.querySelector(`[data-split-break="${i}"]`).value)}));if(rows.some(p=>p.breakMinutes<0||workMinutes(p)<=0))return fail('Each portion must contain worked time after its break.');if(rows.reduce((n,p)=>n+p.breakMinutes,0)!==(t.breakMinutes||0))return fail('Allocate exactly the break minutes recorded on the entry.');t.parts=rows;closeDialog(true);persist();renderComposer();}
  function recipientFields(){const d=initDraft();return `<details class="recipient-details" open><summary>${icon('Mail')}Public recipients · ${d.recipients.length} selected</summary><div class="recipient-list">${sampleUsers.map(u=>`<label><input type="checkbox" data-recipient="${u.id}" ${d.recipients.includes(u.id)?'checked':''}><span><strong>${esc(u.name)}</strong> &lt;${esc(u.email)}&gt;<small>${u.id===s.requesterId?'Requester':u.id===s.affectedId?'Affected user':'Additional site contact'}</small></span></label>`).join('')}</div><p>Only the selected recipients receive this simulated reply. Time and work details stay internal.</p></details>`;}
  function workflowFields(){const w=initDraft().workflow;return `<details class="next-step-editor" ${w.status!=='keep'?'open':''}><summary>${icon('ArrowRight')}Status & next action <span>${w.status==='keep'?'Keep current status':'Update with this note'}</span></summary><div class="two-column">${select('note-status','After saving',[['keep','Keep current status'],['in_progress','In progress'],['waiting','Waiting'],['resolved','Resolve ticket']],w.status)}${select('note-owner','Follow-up owner',names,w.owner)}</div>${w.status==='waiting'||w.status==='in_progress'?`<div class="two-column">${field('note-action','Next action',w.action)}${field('note-due','Follow-up date & time',w.due,'datetime-local')}</div>`:''}${w.status==='waiting'?`<div class="two-column">${select('note-waitingOn','Waiting on',['Affected user','Requester','Vendor','Another technician'],w.waitingOn)}${field('note-reason','Waiting reason',w.reason)}</div>`:''}${w.status==='resolved'?`${select('note-outcome','Resolution outcome',['Service restored','Workaround provided','Request fulfilled','Guidance provided'],w.outcome)}${requiredField('note-verification','How was it checked?',w.verification)}${requiredField('note-publicSummary','Public resolution summary',w.publicSummary,'Shared with the requester; your internal note stays internal.')}<p class="small muted">Required task evidence and approvals must be complete.</p>`:''}</details>`;}
  function recoveryBanner(){return restoredDrafts?`<div class="inline-alert">${icon('Save')}<div class="grow"><strong>Saved work is available in this tab</strong><p>Resume your notes, timing and next-action details from before the refresh.</p></div>${button('Resume draft','resume-draft','RotateCcw','compact')}${button('Discard saved draft','discard-draft','','ghost compact')}</div>`:'';}
  function composer(){let html=original.composer();if(s.status==='closed')return html;html=html.replace(/Public reply · Visible to [^<]+/,'Public reply · Only the selected recipients below').replace('<div class="compose-box">',(s.audience==='public'?recipientFields():'')+'<div class="compose-box">').replace('<div class="compose-footer">',workflowFields()+'<div class="compose-footer">').replace(' Draft stays here while you browse · Ctrl+Enter',storageError?' Draft could not be saved locally':' Draft saved in this tab · Ctrl+Enter');return recoveryBanner()+(draft().timeError&&!draft().time.enabled?`<div class="inline-alert error" role="alert">${icon('TriangleAlert')}${esc(draft().timeError)}</div>`:'')+html;}
  function pendingApprovals(){return [...s.timeEntries.filter(e=>e.afterHours&&e.approval!=='approved'),...s.costs.filter(x=>x.requiresApproval&&x.approval!=='approved')];}
  function validateWorkflow(d){const w=d.workflow;if(d.visitId&&!d.time.enabled)return 'Record actual worked time to complete this technician’s visit.';if(restoredDrafts)return 'Resume or discard the saved draft before adding new work.';if(s.audience==='public'&&!d.recipients.length)return 'Select at least one recipient for the public reply.';if(['waiting','in_progress'].includes(w.status)&&(!w.action.trim()||!Number.isFinite(instant(w.due))||!w.owner))return 'Enter the next action, its owner and a valid follow-up date/time.';if(w.status==='waiting'&&!w.reason.trim())return 'Explain what the ticket is waiting for.';if(w.status==='resolved'){if(!s.taskComplete)return 'Verify the remaining required task before resolving.';if(pendingApprovals().length||(d.time.enabled&&(d.time.parts||[d.time]).some(p=>p.afterHours)))return 'Required after-hours or cost approvals must be complete before resolving.';if(!w.verification.trim()||!w.publicSummary.trim())return 'Record verification and a public resolution summary.';}return '';}
  function send(){if(s.busy||!draft().text.trim())return;captureTime();captureWorkflow();const d=initDraft();d.timeError=timeError(d.time)||validateWorkflow(d);if(d.timeError){renderComposer();return;}const op=d.operationId,copy=structuredClone(d),audience=s.audience;s.busy=true;renderComposer();setTimeout(()=>{s.busy=false;if(s.failNextSend){s.failNextSend=false;draft().error=true;persist();renderComposer();return;}if(s.completedOps.includes(op)){toast('This work was already saved. No duplicate was added.');return;}const id=Math.max(0,...s.messages.map(m=>Number(m.id)||0))+1;const entries=copy.time.enabled?(copy.time.parts||[copy.time]).map(p=>({...p,id:uid(),technician:copy.time.technician,noteId:id,notes:copy.text,approval:p.afterHours?'draft':'not-required',visitId:copy.visitId||null})):[];
      s.messages.push({id,author:'Jordan Lee',initials:'JL',role:'IT technician',time:short(local()),at:local(),internal:audience==='internal',body:copy.text,files:copy.files,recipients:audience==='public'?copy.recipients.map(id=>sampleUsers.find(u=>u.id===id)):[],delivery:'Saved in preview · No notification sent'});s.timeEntries.push(...entries);s.completedOps.push(op);
      const w=copy.workflow;if(w.status!=='keep'){s.status=w.status;s.slaChanged=true;if(['waiting','in_progress'].includes(w.status)){s.followUp={action:w.action,due:w.due,owner:w.owner,waitingOn:w.waitingOn,reason:w.reason};s.waitReason=w.reason;s.nextAction=w.action;}if(w.status==='resolved'){s.resolution={outcome:w.outcome,note:w.publicSummary,verification:w.verification};s.messages.push({id:id+1,author:'Jordan Lee',initials:'JL',role:'IT technician',time:short(local()),internal:false,body:w.publicSummary+'\n\nVerified: '+w.verification,delivery:'Public resolution saved in preview · No notification sent'});}}
      if(copy.visitId){const visit=s.visits.find(v=>v.id===copy.visitId),member=visit?.members.find(m=>m.name===copy.time.technician);if(member){member.status='completed';member.completedAt=local();}}
      recordEvent('NotebookPen','Jordan Lee saved ticket work',`${entries.length?durationLabel(entries.reduce((n,e)=>n+workMinutes(e),0))+' logged · ':''}${w.status==='keep'?'Status retained':w.status.replace('_',' ')}${copy.visitId?' · Visit work recorded':''}`,'work');s.drafts[audience]={text:'',files:[],error:false};s.filter.messages='all';persist();render();toast('Note, time and next steps saved together in this preview.');},550);}
  const priorities={P1:{label:'Critical',tone:'critical',meaning:'Critical service unavailable; urgent coordinated response'},P2:{label:'High',tone:'warning',meaning:'Significant impact; prompt attention needed'},P3:{label:'Medium',tone:'info',meaning:'Limited impact; work can continue'},P4:{label:'Low',tone:'neutral',meaning:'Minor issue or planned assistance'}};
  function priorityBadge(){const p=priorities[s.priority]||priorities.P2;return badge(s.priority+' · '+p.label,p.tone,'ArrowUpRight');}
  function openPriority(){openDialog('priority','Ticket priority','P1–P4 identification · Example impact descriptions, not SLA promises.',`${Object.entries(priorities).map(([code,p])=>`<label class="priority-option"><input name="priority-choice" type="radio" value="${code}" ${s.priority===code?'checked':''}>${badge(code+' · '+p.label,p.tone)}<span>${p.meaning}</span></label>`).join('')}${requiredField('priority-reason','Reason for this priority',s.priorityReason,'Describe the impact and urgency supporting your choice.')}${error()}`,modalFoot(button('Save priority','save-priority','Check','primary')));}
  function savePriority(){if(!validate(['priority-reason']))return;const before={priority:s.priority,reason:s.priorityReason};s.priority=root.querySelector('[name="priority-choice"]:checked').value;s.priorityReason=$('priority-reason').value.trim();history('Priority','IT-2481',before,{priority:s.priority,reason:s.priorityReason},s.priorityReason);closeDialog(true);persist();render();}
  function followUpFields(prefix='follow'){const f=s.followUp;return `<div class="two-column">${field(prefix+'-action','Next action',f.action)}${select(prefix+'-owner','Responsible technician',names,f.owner)}${field(prefix+'-due','Follow-up date & time',f.due,'datetime-local')}${select(prefix+'-waitingOn','Waiting on',['Affected user','Requester','Vendor','Another technician'],f.waitingOn)}</div>${requiredField(prefix+'-reason','Waiting / follow-up reason',f.reason)}${error()}`;}
  function openFollowUp(){openDialog('follow-up','Next action & follow-up','Keep a named person and an exact date/time responsible for progressing this ticket.',followUpFields(),modalFoot(button('Save follow-up','save-follow-up','Check','primary')));}
  function saveFollowUp(){const f=Object.fromEntries(['action','owner','due','waitingOn','reason'].map(k=>[k,$('follow-'+k).value.trim()]));if(!f.action||!f.reason||!Number.isFinite(instant(f.due)))return fail('Enter an action, reason and valid follow-up date/time.');const before=s.followUp;s.followUp=f;s.nextAction=f.action;s.waitReason=f.reason;history('Follow-up','IT-2481',before,f,'Follow-up details updated');closeDialog(true);persist();render();}
  function nextActionCard(){if(['resolved','closed'].includes(s.status))return `<div class="next-action"><div class="eyebrow">${icon('CheckCircle2')}Resolution recorded</div><h2>${s.status==='closed'?'Ticket closed':'Awaiting requester confirmation'}</h2><p>${esc(s.resolution?.note||'Review the recorded outcome.')}</p><div class="status-actions">${s.status==='resolved'?button('Close ticket','close-ticket','Check','compact'):''}${button('Reopen','reopen','RotateCcw','compact')}</div></div>`;const f=s.followUp,overdue=instant(f.due)<Date.now();return `<div class="next-action"><div class="row between"><div class="eyebrow">${icon('ArrowRight')}Next action</div>${overdue?badge('Follow-up overdue','warning','Clock3'):badge('Follow-up set','info','CalendarDays')}</div><h2>${esc(f.action)}</h2><p>${esc(f.reason)}</p><p class="next-due">${icon('CalendarDays')}${stamp(f.due)}</p><p>${esc(f.owner)} · ${s.status==='waiting'?'Waiting on '+esc(f.waitingOn.toLowerCase()):'Responsible technician'}</p><button class="text-link" style="margin-top:12px" data-action="waiting">Edit next action</button></div>`;}
  function contactCard(u,role){const prefs=s.contactPreferences[u.id];return `<section class="person-contact"><div class="row"><span class="avatar">${initials(u.name)}</span><div><h3>${esc(u.name)}</h3><p>${role} · ${esc(u.role)}</p></div></div><button class="contact-line" data-contact-copy="${u.id}:email">${icon('Mail')}<span>${esc(u.email)}</span>${icon('Copy')}</button><button class="contact-line" data-contact-copy="${u.id}:phone">${icon('Phone')}<span>${esc(u.phone)}</span>${icon('Copy')}</button><p class="small muted">Prefers ${esc(prefs.method.toLowerCase())} · ${esc(prefs.window)}</p></section>`;}
  function contacts(){const requester=person('requesterId'),affected=person(),alt=sampleUsers.find(u=>u.id===s.contactPreferences[affected.id].alternate);return `<section class="requester-contact" aria-label="Requester contact details"><div class="row between"><h2>People & contact</h2><button class="text-link small" data-action="requester">Manage</button></div>${requester.id===affected.id?contactCard(affected,'Requester & affected user'):contactCard(requester,'Requester')+contactCard(affected,'Affected user')}<details class="alternate-contact"><summary>Alternate site contact</summary>${alt?contactCard(alt,'Alternate contact'):'Not recorded'}</details></section>`;}
  function requesterDetails(){const u=person(),r=person('requesterId'),prefs=s.contactPreferences[u.id];openDialog('contacts','People & contact','Contact methods, availability and separate requester / affected-user selection.',`<div class="two-column"><div>${contactCard(r,'Requester')}${button('Change requester','choose-requester','Search','compact')}</div><div>${contactCard(u,'Affected user')}${button('Change affected user','choose-affected','Search','compact')}</div></div><div class="contact-settings"><h3>Contact preferences for ${esc(u.name)}</h3><div class="two-column">${select('contact-method','Preferred contact method',['Support portal','Work phone','Work email'],prefs.method)}${field('contact-window','Availability / callback window',prefs.window)}</div>${select('contact-alternate','Alternate site contact',sampleUsers.filter(p=>p.id!==u.id).map(p=>[p.id,p.name]),prefs.alternate)}</div>`,modalFoot(button('Save contact preferences','save-contact-preferences','Check','primary')));}
  function saveContactPreferences(){const id=s.affectedId,before=s.contactPreferences[id];s.contactPreferences[id]={method:$('contact-method').value,window:$('contact-window').value.trim(),alternate:$('contact-alternate').value};history('Contact preferences',id,before,s.contactPreferences[id],'Ticket contact preferences updated');closeDialog(true);persist();render();}
  function diagnosticSummary(){const d=s.diagnostics;return `<details class="surface diagnostic-summary"><summary><span>${icon('Printer')}<strong>Diagnostic summary</strong><small>${esc(d.affected)} people affected · HBR-PRN-02 · Workaround available</small></span>${icon('ChevronDown')}</summary><div class="diagnostic-content"><div class="diagnostic-grid"><div><small>Affected device / service</small><strong>HBR-PRN-02 · Main printer</strong><p>HP LaserJet · Print services</p></div><div><small>Location</small><strong>${esc(d.location)}</strong></div><div><small>First noticed</small><strong>${stamp(d.onset)}</strong><p>${esc(d.affected)} people affected</p></div><div><small>Impact</small><strong>${esc(d.impact)}</strong></div><div><small>Workaround</small><strong>${esc(d.workaround)}</strong></div><div><small>Access instructions</small><strong>${esc(d.access)}</strong></div></div><div class="diagnostic-evidence"><small>Already attempted</small><p>${esc(d.steps.replace('Workstation test remains open.',s.taskComplete?'Workstation test verified: '+s.taskEvidence:'Workstation test remains open.'))}</p></div><div class="row between"><span class="small muted">${esc(d.vendor)}</span><div class="row">${button('Support agreement','vendor-context','FileText','ghost compact')}${button('Edit summary','edit-diagnostics','Pencil','compact')}</div></div></div></details>`;}
  function editDiagnostics(){const d=s.diagnostics;openDialog('diagnostics','Diagnostic summary','Keep concise operational facts visible above the conversation.',`<div class="two-column">${field('diagnostic-onset','First noticed',d.onset,'datetime-local')}${field('diagnostic-affected','People affected',d.affected,'number','min="1"')}${field('diagnostic-location','Precise location',d.location)}${field('diagnostic-impact','Impact',d.impact)}</div>${field('diagnostic-workaround','Current workaround',d.workaround)}${field('diagnostic-access','Access instructions',d.access)}${requiredField('diagnostic-steps','Troubleshooting already attempted',d.steps)}${error()}`,modalFoot(button('Save diagnostic summary','save-diagnostics','Check','primary')),900);}
  function saveDiagnostics(){const before=structuredClone(s.diagnostics),fields=['onset','affected','location','impact','workaround','access','steps'];const d=Object.fromEntries(fields.map(k=>[k,$('diagnostic-'+k).value.trim()]));if(!Number.isFinite(instant(d.onset))||Number(d.affected)<1||!d.location||!d.impact||!d.steps)return fail('Enter a valid onset, affected count, location, impact and troubleshooting summary.');Object.assign(s.diagnostics,d);history('Diagnostic summary','IT-2481',before,s.diagnostics,'Diagnostic context updated');closeDialog(true);persist();render();}
  function contextPanel(){return `<aside class="stack" aria-label="Ticket context"><section class="surface context-card">${nextActionCard()}${contacts()}<details class="context-details"><summary>Ownership & classification ${icon('ChevronDown')}</summary><dl class="context-meta"><div><dt>Owner</dt><dd>${esc(s.owner)} ${button('Change','owner','Search','ghost compact')}</dd></div><div><dt>Team</dt><dd>${esc(s.team)}</dd></div><div><dt>Priority</dt><dd><button data-action="priority">${priorityBadge()}</button></dd></div><div><dt>Site</dt><dd>Harbour Office</dd></div><div><dt>Service</dt><dd>Print services</dd></div></dl>${link('Full classification & links','properties')}</details><div class="context-footer"><button class="text-link" data-action="watchers">${s.watching?'2':'1'} watchers</button><button class="text-link" data-action="watch">${s.watching?'Watching':'Watch ticket'}</button></div></section><div class="quiet-related"><div class="row">${button('Add work note','log-time','NotebookPen','compact')}${button('Schedule help','schedule','CalendarDays','compact')}</div>${link('Review time, costs & approvals →','costs')}</div></aside>`;}
  function header(){original.renderHeader();let priority=$('ticket-priority');if(!priority){priority=document.createElement('button');priority.id='ticket-priority';priority.dataset.action='priority';priority.setAttribute('aria-label','Change ticket priority');$('ticket-status').after(priority);}priority.innerHTML=priorityBadge();const f=s.followUp,active=s.visits.filter(v=>!v.cancelled&&v.members?.some(m=>['requested','accepted'].includes(m.status))).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),next=active[0];$('meters').innerHTML=meter('Next follow-up',['closed','resolved'].includes(s.status)?'Complete':short(f.due),['closed','resolved'].includes(s.status)?'Resolution recorded':f.owner+' · '+f.due.slice(0,10),'properties')+meter('Required work',s.taskComplete?'3 / 3':'2 / 3',s.taskComplete?'Verified complete':'One task still needs evidence','tasks')+meter('Service levels',s.slaChanged?'Unmeasured':s.status==='waiting'?'Paused':'Unmeasured',s.slaChanged?'Policy recalculation needed':'3h 20m remaining at fixture snapshot','sla')+meter('Next visit',next?short(next.date+'T'+next.start):'Unbooked',next?next.date+' · '+next.members.length+' technician(s)':'Schedule additional help','schedule')+meter('Time logged',durationLabel(s.timeEntries.reduce((n,e)=>n+workMinutes(e),0)),durationLabel(s.timeEntries.filter(e=>e.afterHours).reduce((n,e)=>n+workMinutes(e),0))+' marked after hours','time');}
  const minutesOf=hm=>Number(hm.slice(0,2))*60+Number(hm.slice(3));
  function busyFor(name,date,exclude){const fixture=date==='2026-09-13'?(technicians.find(t=>t.name===name)?.busy||[]).map(([a,b])=>({start:a,end:b,label:'Existing appointment'})):[];return [...fixture,...s.visits.filter(v=>v.id!==exclude&&!v.cancelled&&v.date===date&&v.members?.some(m=>m.name===name&&m.status!=='declined')).map(v=>({start:minutesOf(v.start),end:minutesOf(v.end),label:'IT-2481 planned visit'}))];}
  const hm=min=>`${String(Math.floor(min/60)).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`;
  function bookingConflict(){if(!booking?.date||!booking.start||!booking.end||booking.end<=booking.start)return 'Choose an end time after the start.';const namesInConflict=booking.selected.filter(name=>busyFor(name,booking.date,booking.id).some(b=>minutesOf(booking.start)<b.end&&minutesOf(booking.end)>b.start));return namesInConflict.length?'Time conflict for '+namesInConflict.join(', ')+'. Choose another slot.':'';}
  function bookingCapture(){if(!booking)return;['date','start','end','mode','brief','reason'].forEach(k=>{if($('plan-'+k))booking[k]=$('plan-'+k).value;});}
  function availabilityList(){const q=(booking.query||'').toLowerCase();return names.filter(n=>n!==s.owner).filter(n=>(n+' Workplace IT printing field support').toLowerCase().includes(q)).map(name=>{const busy=busyFor(name,booking.date,booking.id),conflict=busy.some(b=>minutesOf(booking.start)<b.end&&minutesOf(booking.end)>b.start);return `<div class="availability-person"><label><input type="checkbox" data-book-person="${name}" ${booking.selected.includes(name)?'checked':''}><span class="avatar">${initials(name)}</span><span><strong>${name}</strong><small>Workplace IT · Harbour Office</small></span>${badge(conflict?'Slot conflict':'Slot available',conflict?'warning':'success',conflict?'Clock3':'Check')}</label><div class="availability-agenda">${busy.length?busy.map(b=>`<span>${short(booking.date+'T'+hm(b.start))}–${short(booking.date+'T'+hm(b.end))} · ${b.label}</span>`).join(''):'No bookings in this synthetic day feed.'}</div></div>`;}).join('')||empty('No matching technicians','Try a name or team.','Search');}
  function openSchedule(id=null){const v=s.visits.find(v=>v.id===id);booking=v?{...structuredClone(v),selected:v.members.filter(m=>m.status!=='declined').map(m=>m.name),query:'',reason:''}:{id:null,date:today(),start:'13:00',end:'14:00',mode:'On site',brief:'Verify workstation printing and investigate the port reset if it recurs.',selected:[],query:'',reason:''};renderBooking();}
  function renderBooking(){openDialog('plan',booking.id?'Reschedule technician visit':'Schedule additional technicians','Review availability and select everyone needed for this work.',`<div class="planning-date"><span>${icon('CalendarDays')}<strong>${booking.date?stamp(booking.date+'T12:00').split(', ')[0]:'Choose a date'}</strong></span><small>Pacific/Auckland · Synthetic day availability</small></div><div class="time-input-grid">${field('plan-date','Date',booking.date,'date')}${field('plan-start','Starts',booking.start,'time')}${field('plan-end','Ends',booking.end,'time')}${select('plan-mode','Location',['On site','Remote'],booking.mode)}</div><div class="slot-suggestions"><span>Try a slot</span>${['09:00','11:00','13:00','15:00'].map(t=>`<button class="of-button compact" data-plan-slot="${t}">${short(booking.date+'T'+t)}</button>`).join('')}</div>${field('plan-search','Search technicians',booking.query,'search')}<div id="availability-list">${availabilityList()}</div><p id="plan-selected" class="selection-summary">${booking.selected.length?booking.selected.join(', '):'Select one or more additional technicians'}</p><p id="plan-conflict" class="field-error" ${bookingConflict()?'':'hidden'}>${esc(bookingConflict())}</p>${requiredField('plan-brief','Work brief',booking.brief)}${booking.id?requiredField('plan-reason','Reason for rescheduling',booking.reason):''}<p class="small muted">Ticket owner remains ${esc(s.owner)}. Saving requests acceptance; it does not confirm attendance or send an invitation.</p>${error()}`,modalFoot(button('Review planned visit','review-plan','ArrowRight','primary')),900);if(booking.selected.length||booking.reason)setDirty();}
  function reviewPlan(){bookingCapture();if(!booking.selected.length)return fail('Select at least one technician.');if(bookingConflict())return fail(bookingConflict());if(!booking.brief.trim()||(booking.id&&!booking.reason.trim()))return fail('Enter the work brief and a rescheduling reason where applicable.');openDialog('plan-review','Review planned visit','All selected technicians will start as Requested in this preview.',`<div class="review-block"><div><small>Technicians</small><p>${esc(booking.selected.join(', '))}</p></div><div><small>Planned time · Pacific/Auckland</small><p>${stamp(booking.date+'T'+booking.start)}–${short(booking.date+'T'+booking.end)} · ${durationLabel(minutesOf(booking.end)-minutesOf(booking.start))}</p></div><div><small>Work brief · ${esc(booking.mode)}</small><p>${esc(booking.brief)}</p></div><div><small>Ticket owner</small><p>${esc(s.owner)}</p></div></div><p class="small muted" style="margin-top:16px">Availability was checked against the synthetic day feed. The production implementation will use the shared SiteCalendar data and approved-site permissions.</p>`,modalFoot(button('Save requested visit','save-plan','Check','primary'),'Back'),720);$('dialog').querySelector('.dialog-footer [data-action="dialog-close"]').dataset.action='back-plan';setDirty();}
  function savePlan(){if(bookingConflict())return fail(bookingConflict());const previous=s.visits.find(v=>v.id===booking.id);const v={id:booking.id||uid(),date:booking.date,start:booking.start,end:booking.end,mode:booking.mode,brief:booking.brief,minutes:minutesOf(booking.end)-minutesOf(booking.start),members:booking.selected.map(name=>({name,status:'requested'})),cancelled:false};if(previous){undoVisit={before:structuredClone(previous),id:v.id};s.visits[s.visits.indexOf(previous)]=v;history('Visit',v.id,previous,v,booking.reason);}else{s.visits.push(v);recordEvent('CalendarDays','Additional help requested',booking.selected.join(', ')+' · '+stamp(v.date+'T'+v.start),'work');}closeDialog(true);persist();go('schedule');toast('Visit requested in preview. No invitations were sent.');}
  function visitState(v){if(v.cancelled)return 'Cancelled';if(v.members.every(m=>m.status==='declined'))return 'Declined';if(v.members.every(m=>['completed','declined'].includes(m.status))&&v.members.some(m=>m.status==='completed'))return 'Completed';if(v.members.some(m=>m.status==='accepted'))return 'Accepted';return 'Requested';}
  function schedulePanel(){const filter=s.filter.schedule||'all',visits=s.visits.filter(v=>filter==='all'||(filter==='active'?['Requested','Accepted'].includes(visitState(v)):visitState(v).toLowerCase()===filter));return `<section class="surface"><div class="section-heading"><div><h2>Scheduled technicians</h2><p>Request → accept → record work → complete</p></div>${button('Schedule technicians','schedule','CalendarDays','compact')}</div>${undoVisit?`<div class="completion-note">Last visit change can be reversed. ${button('Undo visit change','undo-visit','RotateCcw','compact')}</div>`:''}${visits.map(v=>{const actual=s.timeEntries.filter(e=>e.visitId===v.id).reduce((n,e)=>n+workMinutes(e),0),status=visitState(v);return `<article class="visit-entry"><div class="row between"><div><h3>${stamp(v.date+'T'+v.start)}–${short(v.date+'T'+v.end)}</h3><p class="small muted">${esc(v.mode)} · Harbour Office · Pacific/Auckland</p></div>${badge(status,status==='Completed'?'success':status==='Cancelled'||status==='Declined'?'neutral':'info','CalendarDays')}</div><p style="margin:14px 0">${esc(v.brief)}</p><div class="visit-members">${v.members.map(m=>`<div><span class="avatar">${initials(m.name)}</span><strong>${m.name}</strong>${badge(m.status,m.status==='completed'?'success':m.status==='declined'?'warning':'neutral')}<div class="row">${!v.cancelled&&m.status==='requested'?`<button class="of-button compact" data-visit-response="${v.id}" data-member="${m.name}">Record response</button>`:''}${!v.cancelled&&m.status==='accepted'?`<button class="of-button compact" data-visit-work="${v.id}" data-member="${m.name}">${icon('NotebookPen')}Record visit work</button>`:''}${m.reason?`<span class="small muted">${esc(m.reason)}</span>`:''}</div></div>`).join('')}</div><p class="small muted">Planned: ${durationLabel(v.minutes)} per technician · Actual logged: ${durationLabel(actual)} total</p><div class="status-actions">${!['Completed','Cancelled'].includes(status)?`<button class="of-button compact" data-edit-visit="${v.id}">${icon('Pencil')}Reschedule</button><button class="of-button ghost compact" data-cancel-plan="${v.id}">Cancel visit</button>`:''}</div></article>`;}).join('')||empty('No visits in this view','Plan a time, check availability and request the technicians needed.','CalendarDays',button('Schedule technicians','schedule','Plus','compact'))}</section>`;}
  function visitResponse(id,name){decision={id,name};openDialog('visit-response','Record technician response',`${name} · Synthetic response; no communication is sent.`,`${select('response-status','Response',[['accepted','Accepted'],['declined','Declined']],'accepted')}${field('response-reason','Response note / decline reason')}${error()}`,modalFoot(button('Record response','save-response','Check','primary')));}
  function saveResponse(){const v=s.visits.find(v=>v.id===decision.id),m=v.members.find(m=>m.name===decision.name),status=$('response-status').value,reason=$('response-reason').value.trim();if(status==='declined'&&!reason)return fail('Record the reason for declining.');const before=structuredClone(v);m.status=status;m.reason=reason;history('Technician response',v.id,before,v,`${m.name}: ${status}${reason?' — '+reason:''}`);closeDialog(true);persist();render();}
  function completeVisit(id,name){const v=s.visits.find(v=>v.id===id);if(v.cancelled)return;s.audience='internal';const d=initDraft();if(d.text||d.time.start)return toast('Save or discard your current work note before recording visit work.');d.visitId=id;d.time={enabled:true,date:v.date,endDate:v.date,start:'',end:'',type:v.mode==='On site'?'On site':'Remote support',technician:name,afterHours:false,breakMinutes:0};d.text='';go('messages');$('reply-composer').scrollIntoView({block:'start'});$('reply-text').focus({preventScroll:true});persist();}
  function cancelVisit(id){decision={id};openDialog('cancel-visit','Cancel planned visit','Record why the planned work is no longer going ahead.',requiredField('cancel-reason','Cancellation reason'),modalFoot(button('Cancel visit in preview','save-cancel','CalendarDays','primary')));}
  function saveCancel(){if(!validate(['cancel-reason']))return;const v=s.visits.find(v=>v.id===decision.id),before=structuredClone(v);undoVisit={before,id:v.id};v.cancelled=true;v.cancelReason=$('cancel-reason').value.trim();history('Visit',v.id,before,v,v.cancelReason);closeDialog(true);persist();render();}
  function undoChange(){if(!undoVisit)return;const index=s.visits.findIndex(v=>v.id===undoVisit.id);if(index>=0)s.visits[index]=undoVisit.before;recordEvent('RotateCcw','Visit change undone','Restored the previous planned visit in preview.','work');undoVisit=null;persist();render();}
  function linkedTime(m){const entries=s.timeEntries.filter(e=>e.noteId===m.id);return entries.length?`<div class="message-work-log">${icon('Clock3')}<strong>${durationLabel(entries.reduce((n,e)=>n+workMinutes(e),0))}</strong><span>${entries.length} linked time ${entries.length===1?'entry':'entries'} · ${durationLabel(entries.filter(e=>e.afterHours).reduce((n,e)=>n+workMinutes(e),0))} after hours</span>${link('View work entries','time')}</div>`:'';}
  function message(m){return original.message(m).replace('</div></article>',`${m.author==='Jordan Lee'?`<div class="message-actions"><button class="text-link small" data-correct-note="${m.id}">Correct note</button><button class="text-link small" data-record-history="note:${m.id}">Change history</button></div>`:''}${m.recipients?.length?`<p class="small muted">Recipients: ${m.recipients.map(u=>esc(u.name)+' &lt;'+esc(u.email)+'&gt;').join(', ')}</p>`:''}</div></article>`);}
  function editNote(id){const m=s.messages.find(m=>m.id===id);if(s.timeEntries.some(e=>e.noteId===id&&e.approval==='approved'))return toast('Request a correction for the approved time entry before changing its linked note.');editing={kind:'note',id};openDialog('correct-note','Correct work note','The previous text will remain in change history.',`${requiredField('correction-note','Corrected note',m.body)}${requiredField('correction-reason','Reason for correction')}${error()}`,modalFoot(button('Save correction','save-note-correction','Check','primary')));}
  function saveNoteCorrection(){if(!validate(['correction-note','correction-reason']))return;const m=s.messages.find(m=>m.id===editing.id),before=structuredClone(m),reason=$('correction-reason').value.trim();m.body=$('correction-note').value.trim();m.editedAt=local();s.timeEntries.filter(e=>e.noteId===m.id).forEach(e=>e.notes=m.body);history('Note',m.id,before,m,reason);closeDialog(true);persist();render();}
  function openTime(id){const e=s.timeEntries.find(x=>String(x.id)===String(id));if(!e)return;if(e.approval==='approved')return requestCorrection(e.id);editing={kind:'time',id:e.id};openDialog('correct-time','Correct time entry','Record why the timing changed. The previous values remain in history.',`<div class="locked-context">${icon('UserRound')}<strong>${esc(e.technician)}</strong><span>Recorded by Jordan Lee</span></div><div class="two-column">${field('correction-start','Started',e.start,'datetime-local')}${field('correction-end','Ended',e.end,'datetime-local')}${field('correction-break','Break minutes',e.breakMinutes||0,'number','min="0"')}${select('correction-type','Work type',['Remote support','On site','Travel'],e.type)}</div><label class="after-hours-choice"><input id="correction-after" type="checkbox" ${e.afterHours?'checked':''}><span><strong>Work was done after hours</strong><small>Correcting time uses the entered start/end and break duration.</small></span></label>${requiredField('correction-reason','Reason for correction')}<p class="small muted">The linked note text is unchanged. Use Correct note to amend the description.</p>${error()}`,modalFoot(button('Save time correction','save-time-correction','Check','primary')));}
  function saveTimeCorrection(){if(!validate(['correction-reason']))return;const e=s.timeEntries.find(e=>e.id===editing.id),copy={...e,start:$('correction-start').value,end:$('correction-end').value,breakMinutes:Number($('correction-break').value),type:$('correction-type').value,afterHours:$('correction-after').checked,segments:null,parts:null,timer:null,enabled:true};const problem=timeError(copy,[e.id]);if(problem)return fail(problem);const before=structuredClone(e);copy.approval=copy.afterHours?'draft':'not-required';Object.assign(e,copy);history('Time entry',e.id,before,e,$('correction-reason').value.trim());closeDialog(true);persist();render();}
  function requestCorrection(id){editing={kind:'time',id};openDialog('unlock-time','Request correction to approved time','This returns the entry to review before its values can change.',requiredField('unlock-reason','Reason for requesting correction'),modalFoot(button('Return entry for correction','unlock-time','RotateCcw','primary')));}
  function unlockTime(){if(!validate(['unlock-reason']))return;const e=s.timeEntries.find(e=>e.id===editing.id),before=structuredClone(e);e.approval='draft';history('Time approval',e.id,before,e,$('unlock-reason').value.trim());const id=e.id;closeDialog(true);persist();openTime(id);}
  function approvalBadge(e){return e.approval==='approved'?badge('Approved','success','ShieldCheck'):e.approval==='pending'?badge('Awaiting approval','warning','Clock3'):e.approval==='rejected'?badge('Needs changes','critical','Pencil'):e.afterHours||e.requiresApproval?badge('Approval required','warning','ShieldCheck'):badge('No approval required','neutral');}
  function timePanel(){const f=s.filter.time||'all',entries=s.timeEntries.filter(e=>f==='all'||f==='after-hours'&&e.afterHours||e.type===f);return `<section class="surface"><div class="section-heading"><div><h2>Time entries</h2><p>Notes, actual worked time, breaks and corrections · Pacific/Auckland</p></div>${button('Add work note','log-time','NotebookPen','compact')}</div><div class="time-totals"><div><span>Total worked</span><strong>${durationLabel(s.timeEntries.reduce((n,e)=>n+workMinutes(e),0))}</strong></div><div><span>After hours</span><strong>${durationLabel(s.timeEntries.filter(e=>e.afterHours).reduce((n,e)=>n+workMinutes(e),0))}</strong></div><div><span>Travel</span><strong>${durationLabel(s.timeEntries.filter(e=>e.type==='Travel').reduce((n,e)=>n+workMinutes(e),0))}</strong></div></div>${entries.map(e=>`<article class="time-entry"><div class="row between"><div class="row"><span class="avatar">${initials(e.technician)}</span><h3>${esc(e.technician)} <span class="small muted">· ${esc(e.type)}</span></h3></div><div class="row">${e.afterHours?badge('After hours','warning','Clock3'):''}<strong>${durationLabel(workMinutes(e))}</strong></div></div><div class="entry-range"><div><span>Started</span><strong>${stamp(e.start)}</strong></div>${icon('ArrowRight')}<div><span>Ended</span><strong>${stamp(e.end)}</strong></div><div><span>Breaks</span><strong>${e.segments?.length?'Timer pauses excluded':durationLabel(e.breakMinutes||0)}</strong></div></div><p>${esc(e.notes)}</p><div class="entry-actions">${approvalBadge(e)}${e.afterHours&&['draft','rejected',undefined].includes(e.approval)?`<button class="of-button compact" data-request-approval="time:${e.id}">Request approval</button>`:''}<button class="of-button compact ghost" data-edit-time="${e.id}">${e.approval==='approved'?'Request correction':'Correct time'}</button>${e.noteId?`<button class="text-link small" data-view-note="${e.noteId}">Linked note</button>`:''}<button class="text-link small" data-record-history="time:${e.id}">Change history</button></div></article>`).join('')||empty('No matching time entries','Choose All time entries to see the full work log.','Clock3')}<div class="sla-evidence-note">Example approval rule: after-hours entries require review before resolution. Approved entries must be returned for correction before editing.</div></section>`;}
  function readable(value){if(value===undefined||value===null||value==='')return '—';if(typeof value==='boolean')return value?'Yes':'No';if(Array.isArray(value))return value.map(x=>typeof x==='object'?(x.name||x.technician||'Entry')+(x.status?' · '+x.status:''):x).join(', ');if(typeof value==='object')return Object.entries(value).map(([k,v])=>k+': '+readable(v)).join(' · ');return String(value);}
  function revisionDetails(record){const labels={body:'Note',notes:'Work description',start:'Started',end:'Ended',breakMinutes:'Break minutes',type:'Work type',afterHours:'After hours',technician:'Technician',approval:'Approval state',priority:'Priority',reason:'Reason',due:'Follow-up due',action:'Next action',owner:'Responsible person',members:'Technician responses',date:'Date',brief:'Work brief',cancelled:'Cancelled',amount:'Amount',label:'Description',method:'Contact method',window:'Availability',alternate:'Alternate contact',location:'Location',impact:'Impact',steps:'Troubleshooting',workaround:'Workaround',onset:'First noticed',affected:'People affected',access:'Access instructions',standard:'Standard hourly rate'};return `<dl class="revision-values">${Object.entries(record).filter(([k])=>labels[k]).map(([k,v])=>`<dt>${labels[k]}</dt><dd>${esc(readable(v))}</dd>`).join('')}</dl>`;}
  function changeHistory(filter=''){const [kind,id]=filter.split(':');const revisions=s.corrections.filter(x=>!id||String(x.record)===id);openDialog('history','Change history','Previous values, the person recording the change, and the reason.',revisions.map(x=>`<section class="correction-card"><h3>${esc(x.kind)} · ${stamp(x.at)}</h3><p class="small muted">${esc(x.by)} · ${esc(x.reason)}</p><div class="two-column"><div><h4>Before</h4>${revisionDetails(x.before)}</div><div><h4>After</h4>${revisionDetails(x.after)}</div></div></section>`).join('')||empty('No corrections recorded','New corrections will retain the previous values here.','Activity'),modalFoot('','Close'),900);}
  function correctionsPanel(){return `<section class="surface"><div class="section-heading"><div><h2>Corrections & decisions</h2><p>Who changed the record, when, and why</p></div>${button('View full change history','full-history','Activity','compact')}</div>${s.corrections.map(x=>`<div class="list-row"><span class="record-icon">${icon('Pencil')}</span><div class="grow"><h3>${esc(x.kind)} · ${esc(x.by)}</h3><p>${stamp(x.at)} · ${esc(x.reason)}</p></div><button class="of-button compact" data-record-history="record:${x.record}">Before & after</button></div>`).join('')||empty('No corrections yet','Original values are retained whenever a correction or decision is recorded.','Activity')}</section>`;}
  const labourCost=()=>s.timeEntries.reduce((n,e)=>n+workMinutes(e)/60*(e.afterHours?s.rates.afterHours:s.rates.standard),0);
  function costsPanel(){const filter=s.filter.costs||'all',costs=s.costs.filter(x=>filter==='all'||x.type===filter);return `<section class="surface"><div class="section-heading"><div><h2>Parts, expenses & internal costs</h2><p>Illustrative NZD amounts · No invoices or financial transactions</p></div>${button('Add part or expense','add-cost','Plus','compact')}</div><div class="time-totals"><div><span>Internal labour</span><strong>${money(labourCost())}</strong></div><div><span>Parts & expenses</span><strong>${money(s.costs.reduce((n,x)=>n+x.amount,0))}</strong></div><div><span>Total illustrative cost</span><strong>${money(labourCost()+s.costs.reduce((n,x)=>n+x.amount,0))}</strong></div></div><div class="completion-note">Example hourly rates: ${money(s.rates.standard)} standard / ${money(s.rates.afterHours)} after hours. ${button('Edit example rates','edit-rates','Pencil','ghost compact')}</div>${costs.map(x=>`<article class="cost-entry"><div class="row between"><div><h3>${esc(x.label)}</h3><p class="small muted">${esc(x.type)} · ${x.quantity} × ${money(x.unitCost)} · ${esc(x.date)} · ${esc(x.reference||'No reference')}</p></div><strong>${money(x.amount)}</strong></div><p>${esc(x.notes)}</p><div class="entry-actions">${approvalBadge(x)}${x.requiresApproval&&['draft','rejected'].includes(x.approval)?`<button class="of-button compact" data-request-approval="cost:${x.id}">Request approval</button>`:''}<button class="text-link small" data-edit-cost="${x.id}">Correct cost</button><button class="text-link small" data-record-history="cost:${x.id}">Change history</button></div></article>`).join('')||empty('No parts or expenses recorded','Add parts used, travel expenses or other internal costs for this ticket.','Wallet',button('Add part or expense','add-cost','Plus','compact'))}<div class="sla-evidence-note">Example rule: costs of $100 or more require approval before resolution. You can also request approval for a smaller item. Billing is not enabled.</div></section>`;}
  function openCost(id=null){const x=s.costs.find(x=>x.id===id)||{type:'Part',label:'',quantity:1,unitCost:0,date:today(),reference:'',notes:'',requiresApproval:false};if(x.approval==='approved')return toast('An approved cost is locked. Use Approvals to return it for changes first.');editing={kind:'cost',id};openDialog('cost',id?'Correct recorded cost':'Add part or expense','Record the item and illustrative internal cost.',`<div class="two-column">${select('cost-type','Type',['Part','Expense','Travel expense'],x.type)}${field('cost-date','Date',x.date,'date')}</div>${field('cost-label','Item / expense description',x.label)}<div class="two-column">${field('cost-quantity','Quantity',x.quantity,'number','min="0.01" step="0.01"')}${field('cost-unit','Unit cost (NZD)',x.unitCost,'number','min="0" step="0.01"')}</div>${field('cost-reference','Receipt / vendor reference',x.reference)}${field('cost-notes','Notes',x.notes)}<label class="dialog-check"><input id="cost-approval" type="checkbox" ${x.requiresApproval?'checked':''}>Require approval before resolution</label>${id?requiredField('cost-reason','Reason for correction'):''}${error()}`,modalFoot(button(id?'Save cost correction':'Add cost','save-cost','Check','primary')));}
  function saveCost(){const quantity=Number($('cost-quantity').value),unitCost=Number($('cost-unit').value),amount=Math.round(quantity*unitCost*100)/100;if(!$('cost-label').value.trim()||!$('cost-date').value||!Number.isFinite(amount)||quantity<=0||unitCost<0)return fail('Enter a description, date, positive quantity and non-negative cost.');if(editing.id&&!validate(['cost-reason']))return;const x={id:editing.id||uid(),label:$('cost-label').value.trim(),date:$('cost-date').value,type:$('cost-type').value,quantity,unitCost,amount,reference:$('cost-reference').value.trim(),notes:$('cost-notes').value.trim(),requiresApproval:$('cost-approval').checked||amount>=100,approval:'draft'};if(editing.id){const old=s.costs.find(c=>c.id===editing.id);history('Cost',x.id,old,x,$('cost-reason').value.trim());s.costs[s.costs.indexOf(old)]=x;}else{s.costs.push(x);recordEvent('Wallet','Internal cost recorded',x.label+' · '+money(amount),'work');}closeDialog(true);persist();go('costs');}
  function editRates(){openDialog('rates','Illustrative internal labour rates','These sample rates support the mockup calculation only.',`<div class="two-column">${field('rate-standard','Standard hourly rate (NZD)',s.rates.standard,'number','min="0" step="0.01"')}${field('rate-after','After-hours hourly rate (NZD)',s.rates.afterHours,'number','min="0" step="0.01"')}</div>${requiredField('rate-reason','Reason for changing the sample rates')}${error()}`,modalFoot(button('Apply example rates','save-rates','Check','primary')));}
  function saveRates(){const rates={standard:Number($('rate-standard').value),afterHours:Number($('rate-after').value)};if(Object.values(rates).some(x=>!Number.isFinite(x)||x<0))return fail('Enter non-negative rates.');if(!validate(['rate-reason']))return;history('Example labour rates','rates',s.rates,rates,$('rate-reason').value.trim());s.rates=rates;closeDialog(true);persist();render();}
  function approvalRecord(key){const split=key.indexOf(':');const kind=key.slice(0,split),id=key.slice(split+1);return {kind,record:(kind==='time'?s.timeEntries:s.costs).find(x=>String(x.id)===id)};}
  function requestApproval(key){const {kind,record}=approvalRecord(key);if(!record)return;record.approval='pending';record.requestedAt=local();recordEvent('ShieldCheck','Approval requested',kind==='time'?record.technician+' · '+durationLabel(workMinutes(record)):record.label,'work');persist();render();toast('Approval requested in preview. No notification sent.');}
  function approvalDecision(key){decision={key};const {kind,record}=approvalRecord(key);openDialog('approval-decision','Preview supervisor decision',`${kind==='time'?record.technician+' · '+durationLabel(workMinutes(record)):record.label+' · '+money(record.amount)}`,`<div class="inline-alert">${icon('FlaskConical')}Simulated supervisor role: Alex Reed. The technician does not approve their own time in the production workflow.</div>${select('approval-result','Decision',[['approved','Approve'],['rejected','Return for changes']],'approved')}${requiredField('approval-reason','Decision reason')}${error()}`,modalFoot(button('Record simulated decision','save-approval-decision','ShieldCheck','primary')));}
  function saveApprovalDecision(){if(!validate(['approval-reason']))return;const {kind,record}=approvalRecord(decision.key),before=structuredClone(record);record.approval=$('approval-result').value;record.reviewedBy='Alex Reed (simulated supervisor)';record.reviewReason=$('approval-reason').value.trim();history(kind==='time'?'Time approval':'Cost approval',record.id,before,record,record.reviewReason);s.corrections[0].by=record.reviewedBy;closeDialog(true);persist();render();}
  function approvalsPanel(){const records=[...s.timeEntries.filter(x=>x.afterHours||x.approval==='pending'||x.approval==='approved').map(x=>({kind:'time',x})),...s.costs.filter(x=>x.requiresApproval).map(x=>({kind:'cost',x}))];return `<section class="surface"><div class="section-heading"><div><h2>Work & cost approvals</h2><p>Example rules · After-hours time and costs requiring review</p></div>${badge(pendingApprovals().length+' unresolved',pendingApprovals().length?'warning':'success','ShieldCheck')}</div>${records.map(({kind,x})=>`<div class="list-row"><span class="record-icon">${icon('ShieldCheck')}</span><div class="grow"><h3>${kind==='time'?esc(x.technician)+' · '+durationLabel(workMinutes(x)):esc(x.label)+' · '+money(x.amount)}</h3><p>${kind==='time'?'After-hours time':'Internal cost'} · ${esc(x.reviewReason||'Review required before resolution')}</p>${x.reviewedBy?`<p>${esc(x.reviewedBy)}</p>`:''}</div><div class="end">${approvalBadge(x)}${x.approval==='draft'||x.approval==='rejected'?`<button class="of-button compact" data-request-approval="${kind}:${x.id}">Request approval</button>`:`<button class="of-button compact" data-review-approval="${kind}:${x.id}">${x.approval==='approved'?'Review decision':'Preview supervisor decision'}</button>`}</div></div>`).join('')||empty('No approvals required yet','After-hours time and costs meeting the sample rule appear here when recorded.','ShieldCheck')}</section>`;}
  function guardedResolve(){if(pendingApprovals().length)return openDialog('approval-blocked','Required approvals are outstanding','Review the after-hours time and costs before resolving this ticket.',`<p>${pendingApprovals().length} record(s) still require approval under the example rules.</p>`,modalFoot(button('Review approvals','go-approvals','ShieldCheck','primary')),480);original.openResolve();}
  function coverage(){openDialog('coverage','Workflow coverage','All requested improvements are interactive in this isolated mockup.',`<div class="coverage-intro">Try the note composer, Work sections and People & contact. P1–P4 priority is beside the ticket title.</div>${[['Combined work save','Note, actual time, status, next action and follow-up owner/date save together. Task verification and approvals still block resolution.'],['Time tools','Manual start/end, default date, timer with pause/resume/stop, breaks, travel, overnight work and reviewed after-hours splits.'],['Technician scheduling','Search, day availability, multiple technicians, requests, responses, cancellations with undo and completion through recorded work.'],['People & communication','Separate requester and affected-user contacts, preferences, alternate contact and explicit public recipients.'],['Context & hierarchy','Compact diagnostic summary, prominent next action, P1–P4 identification and five relevant header meters.'],['Corrections & recovery','Draft resume after refresh, one operation per save, retained note/time versions and reasons, approval locks and correction requests.'],['Costs & approvals','Parts, expenses, illustrative internal labour rates and a clearly labelled supervisor decision simulation.']].map(([title,copy],i)=>`<section class="coverage-row"><span class="coverage-number">${i+1}</span><div><h3>${title}</h3><p>${copy}</p></div></section>`).join('')}<p class="small muted" style="margin-top:18px">Production work remains: API transactions and retries, permissions, server draft storage, directory and SiteCalendar integration, notifications, authoritative SLA policy and agreed approval/rate rules. This preview uses no real records, credentials, invitations or billing.</p>`,modalFoot('','Close'),900);}
  function renderPanel(){if(s.tab==='costs'||s.tab==='corrections'){$('ticket-panel').innerHTML=`<div class="workspace-grid">${s.tab==='costs'?costsPanel():correctionsPanel()}${contextPanel()}</div>`;}else{original.renderPanel();if(s.tab==='messages'){$('ticket-panel').querySelector('.workspace-grid').insertAdjacentHTML('beforebegin',diagnosticSummary());}if(s.tab==='properties'){const label=[...$('ticket-panel').querySelectorAll('dt')].find(el=>el.textContent==='Priority');if(label)label.nextElementSibling.innerHTML=priorityBadge()+'<p class="small muted">'+esc(s.priorityReason)+'</p>'+button('Change priority','priority','Pencil','ghost compact');$('ticket-panel').insertAdjacentHTML('afterbegin',`<div class="surface follow-up-summary">${nextActionCard()}</div>${diagnosticSummary()}`);}}}
  function composerRefresh(){original.renderComposer();persist();}
  function fullRender(){original.render();persist();}
  function draftIndicator(){original.renderDraftIndicator();if(restoredDrafts)$('retained-draft').textContent='Saved draft available · Resume in Conversation';else if(!storageError&&Object.values(s.drafts).some(d=>d.text||d.time?.start))$('retained-draft').insertAdjacentHTML('beforeend',' · Saved in this tab');}
  const actions={
    send,priority:openPriority,'save-priority':savePriority,waiting:openFollowUp,'save-follow-up':saveFollowUp,
    requester:requesterDetails,'save-contact-preferences':saveContactPreferences,
    'edit-diagnostics':editDiagnostics,'save-diagnostics':saveDiagnostics,
    'vendor-context':()=>openDialog('vendor-context','Support agreement & approved access','Synthetic operational references for this ticket.',`<dl class="property-list"><dt>Vendor</dt><dd>${esc(s.diagnostics.vendor)}</dd><dt>Agreement</dt><dd>${esc(s.diagnostics.contract)}</dd><dt>Support route</dt><dd>Use the approved vendor support record to request assistance.</dd><dt>Device access</dt><dd>Open the approved device record and credential reference with the appropriate permission.</dd><dt>Location access</dt><dd>${esc(s.diagnostics.access)}</dd></dl><p class="small muted" style="margin-top:18px">No credential values are stored in the ticket or this mockup.</p>`,modalFoot('','Close')),
    'timer-start':()=>timerAction('start'),'timer-pause':()=>timerAction('pause'),'timer-resume':()=>timerAction('resume'),'timer-stop':()=>timerAction('stop'),
    'timer-replace':()=>{closeDialog(true);initDraft().time.timer=null;timerAction('start');},'split-time':splitTime,'apply-split':applySplit,
    schedule:()=>openSchedule(),'review-plan':reviewPlan,'save-plan':savePlan,'back-plan':renderBooking,'save-response':saveResponse,'save-cancel':saveCancel,'undo-visit':undoChange,
    'save-note-correction':saveNoteCorrection,'save-time-correction':saveTimeCorrection,'unlock-time':unlockTime,'full-history':()=>changeHistory(),
    'add-cost':()=>openCost(),'save-cost':saveCost,'edit-rates':editRates,'save-rates':saveRates,'save-approval-decision':saveApprovalDecision,
    resolve:guardedResolve,'go-approvals':()=>{closeDialog(true);go('approvals');},
    'resume-draft':()=>{s.drafts=restoredDrafts;restoredDrafts=null;persist();render();toast('Saved note and timing restored.');},
    'discard-draft':()=>{restoredDrafts=null;s.drafts={public:{text:'',files:[],error:false},internal:{text:'',files:[],error:false}};persist();render();},
    'coverage-review':coverage,
    'reset-confirm':()=>{restoredDrafts=null;s.drafts={public:{text:'',files:[],error:false},internal:{text:'',files:[],error:false}};sessionStorage.removeItem(KEY);location.reload();}
  };
  root.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;let handled=true;
    if(el.dataset.contactCopy){const [id,key]=el.dataset.contactCopy.split(':');c.copyText(sampleUsers.find(u=>u.id===id)[key],'Synthetic contact copied.');}
    else if(el.dataset.planSlot){bookingCapture();booking.start=el.dataset.planSlot;booking.end=hm(minutesOf(booking.start)+60);renderBooking();}
    else if(el.dataset.visitResponse)visitResponse(el.dataset.visitResponse,el.dataset.member);
    else if(el.dataset.visitWork)completeVisit(el.dataset.visitWork,el.dataset.member);
    else if(el.dataset.cancelPlan)cancelVisit(el.dataset.cancelPlan);
    else if(el.dataset.correctNote)editNote(Number(el.dataset.correctNote));
    else if(el.dataset.recordHistory)changeHistory(el.dataset.recordHistory);
    else if(el.dataset.editCost)openCost(el.dataset.editCost);
    else if(el.dataset.requestApproval)requestApproval(el.dataset.requestApproval);
    else if(el.dataset.reviewApproval)approvalDecision(el.dataset.reviewApproval);
    else handled=false;
    if(handled){event.preventDefault();event.stopImmediatePropagation();}
  },true);
  root.addEventListener('input',event=>{const el=event.target;if(el.id.startsWith('work-')){const d=initDraft();d.time.parts=null;if(el.id!=='work-after-hours'&&el.id!=='work-type'){d.time.segments=null;d.time.timer=null;}captureTime();const mins=workMinutes(d.time);if($('note-duration'))$('note-duration').textContent=Number.isFinite(mins)&&mins>0?durationLabel(mins):'Check start, end and breaks';}
    if(el.id.startsWith('note-'))captureWorkflow();
    if(el.id==='plan-search'){booking.query=el.value;$('availability-list').innerHTML=availabilityList();}
    if(['plan-date','plan-start','plan-end'].includes(el.id)){bookingCapture();$('availability-list').innerHTML=availabilityList();const conflict=bookingConflict();$('plan-conflict').textContent=conflict;$('plan-conflict').hidden=!conflict;const anchor=root.querySelector('.planning-date strong');anchor.textContent=booking.date?stamp(booking.date+'T12:00').split(', ')[0]:'Choose a date';}
    if(el.closest('dialog')&&!['plan-search','user-search','owner-search'].includes(el.id))setDirty();
    setTimeout(persist,0);
  });
  root.addEventListener('change',event=>{const el=event.target;if(el.dataset.recipient){const d=initDraft();d.recipients=el.checked?[...new Set([...d.recipients,el.dataset.recipient])]:d.recipients.filter(id=>id!==el.dataset.recipient);persist();}
    if(el.dataset.bookPerson){booking.selected=el.checked?[...new Set([...booking.selected,el.dataset.bookPerson])]:booking.selected.filter(n=>n!==el.dataset.bookPerson);$('plan-selected').textContent=booking.selected.join(', ')||'Select one or more additional technicians';$('plan-conflict').textContent=bookingConflict();$('plan-conflict').hidden=!bookingConflict();}
    if(el.id==='note-status'){captureWorkflow();renderComposer();}
    if(el.id.startsWith('work-')){captureTime();persist();}
    setTimeout(persist,0);
  });
  setInterval(()=>{const t=draft()?.time;if(t?.timer?.runningSince&&$('timer-value')){const seconds=Math.floor(timerMinutes(t)*60);$('timer-value').textContent=`${Math.floor(seconds/60)}m ${String(seconds%60).padStart(2,'0')}s`; }},1000);
  groups.find(g=>g.key==='work').tabs.push(['costs','Parts & costs','Wallet']);
  groups.find(g=>g.key==='activity').tabs.push(['corrections','Corrections','Pencil']);
  return {actions,overrides:{composer,noteTimeFields:timeFields,captureNoteTime:captureTime,noteTimeError:timeError,send,
    contextPanel,requesterDetails,renderHeader:header,renderPanel,render:fullRender,renderComposer:composerRefresh,
    renderDraftIndicator:draftIndicator,openSchedule,schedulePanel,timePanel,approvalsPanel,openTime,linkedTime,message,
    entryMinutes:workMinutes,openResolve:guardedResolve},persist};
};
